"use strict";(self.webpackChunkhamrang_log=self.webpackChunkhamrang_log||[]).push([[5894],{6042:n=>{n.exports=JSON.parse('{"blogPosts":[{"id":"feature-sliced-design","metadata":{"permalink":"/blog/feature-sliced-design","editUrl":"https://github.com/eeheueklf/eeheueklf.github.io/tree/main/blog/2026-04-20.md","source":"@site/blog/2026-04-20.md","title":"\ud83e\udd16Gemini\uc640 \uc54c\uc544\ubcf8 \ud604\uc5c5\uc5d0\uc11c \uc4f0\ub294 \ud3f4\ub354 \uad00\ub9ac","description":"\ud559\uad50\uc5d0\uc11c, \uadf8\ub9ac\uace0 \uac1c\uc778\uc801\uc73c\ub85c \uc5ec\ub7ec \ud504\ub85c\uc81d\ud2b8\ub97c \uc9c4\ud589\ud558\uba74\uc11c \ud3f4\ub354 \uad6c\uc870\uc758 \uc815\ub2f5\uc744 \ucad3\uc544\uc654\ub2e4. \uc5b4\ub5a4 \uad6c\uc870\uac00 \uac00\uc7a5 \ud6a8\uc728\uc801\uc778\uc9c0, \uc2e4\uc81c \ud604\uc5c5\uc5d0\uc11c\ub294 \uc5b4\ub5a4 \ubc29\uc2dd\uc744 \uc0ac\uc6a9\ud558\ub294\uc9c0 \ud56d\uc0c1 \uad81\uae08\ud588\uc9c0\ub9cc \ucc38\uace0\ud560 \ub9cc\ud55c \ub808\ud37c\ub7f0\uc2a4\ub97c \ucc3e\uae30\uac00 \uc27d\uc9c0 \uc54a\uc558\ub2e4.","date":"2026-04-20T00:00:00.000Z","formattedDate":"2026\ub144 4\uc6d4 20\uc77c","tags":[],"readingTime":4.715,"hasTruncateMarker":false,"authors":[],"frontMatter":{"slug":"feature-sliced-design","title":"\ud83e\udd16Gemini\uc640 \uc54c\uc544\ubcf8 \ud604\uc5c5\uc5d0\uc11c \uc4f0\ub294 \ud3f4\ub354 \uad00\ub9ac","date":"2026-04-20T00:00:00.000Z"},"unlisted":false,"nextItem":{"title":"Next.js\uac00 \ud568\uc815\uc774\uc5c8\ub358 \ud0c0\uc790 \uc5f0\uc2b5 \ud504\ub85c\uc81d\ud2b8 \ud68c\uace0","permalink":"/blog/next-sidepj"}},"content":"\ud559\uad50\uc5d0\uc11c, \uadf8\ub9ac\uace0 \uac1c\uc778\uc801\uc73c\ub85c \uc5ec\ub7ec \ud504\ub85c\uc81d\ud2b8\ub97c \uc9c4\ud589\ud558\uba74\uc11c \ud3f4\ub354 \uad6c\uc870\uc758 **\uc815\ub2f5**\uc744 \ucad3\uc544\uc654\ub2e4. \uc5b4\ub5a4 \uad6c\uc870\uac00 \uac00\uc7a5 \ud6a8\uc728\uc801\uc778\uc9c0, \uc2e4\uc81c \ud604\uc5c5\uc5d0\uc11c\ub294 \uc5b4\ub5a4 \ubc29\uc2dd\uc744 \uc0ac\uc6a9\ud558\ub294\uc9c0 \ud56d\uc0c1 \uad81\uae08\ud588\uc9c0\ub9cc \ucc38\uace0\ud560 \ub9cc\ud55c \ub808\ud37c\ub7f0\uc2a4\ub97c \ucc3e\uae30\uac00 \uc27d\uc9c0 \uc54a\uc558\ub2e4.\\r\\n\\r\\n\uacfc\uac70, \uaddc\ubaa8\uac00 \uc791\uc740 \uac1c\uc778 \ud504\ub85c\uc81d\ud2b8\uc5d0 \uc138\ubd84\ud654\ub41c \uad6c\uc870\ub97c \uc801\uc6a9\ud558\uba74\uc11c **\uacfc\ubd84\ub9ac**\ub77c\ub294 \ub290\ub08c\uc744 \ubc1b\uc558\ub358 \uc801\ub3c4 \uc788\ub2e4. \ud558\uc9c0\ub9cc \ucf54\ub4dc \ub9ac\ud329\ud1a0\ub9c1\uc744 \ud558\uba74\uc11c `hook`\uacfc `service`, `ui`\ub97c \ubd84\ub9ac\ud588\uc744\ub54c \uc5bb\ub294 \uc720\uc9c0\ubcf4\uc218\uc131\uc758 \uc774\uc810\uc774 \ud6e8\uc52c \ud06c\ub2e4\ub294 \uac83\uc744 \uae68\ub2ec\uc558\ub2e4. \\r\\n\\r\\n\uc774\uc81c\ub294 `Gemini`\uc640 \ud568\uaed8 \ud604\uc5c5\uc5d0\uc11c \uc5b4\ub5a4 \uad6c\uc870\uac00 \ub9ce\uc774 \uc4f0\uc774\ub294\uc9c0, **\ud3f4\ub354 \uad6c\uc870\uc758 \uc815\ub2f5\uc774 \uc788\ub294\uc9c0** \uc54c \uc218 \uc788\uac8c \ub418\uc5c8\ub2e4. `Gemini`\ub294 \uc5b4\ub514\uc11c \ud3f4\ub354 \uad6c\uc870\ub97c \ucc38\uace0\ud558\uc600\ub294\uc9c0 \ud0d0\uad6c\ud574\ubcf4\uc790.\\r\\n\\r\\n## \ud3f4\ub354 \uad6c\uc870\uc758 \uad50\uacfc\uc11c\\r\\n\\r\\n[Bulletproof-React](https://github.com/alan2207/bulletproof-react)  \\r\\n`Gemini`\uac00 \ub9d0\ud558\ub294 **\ud3f4\ub354 \uad6c\uc870\uc758 \uad50\uacfc\uc11c**\ub85c \ud1b5\ud558\ub294 \ub808\ud3ec\uc9c0\ud1a0\ub9ac\uc774\ub2e4. \uc774 \ud504\ub85c\uc81d\ud2b8\uc758 \ud575\uc2ec\uc740 \uae30\ub2a5 \uae30\ubc18 \uad6c\uc870\uc5d0 \uc788\ub2e4.\\r\\n\\r\\n`A simple, scalable, and powerful architecture for building production ready React applications.`\\r\\n\\r\\n`components`, `hook` \ud3f4\ub354\uc5d0 \ubaa8\ub4e0 \ud30c\uc77c\uc744 \ub123\ub294 \uac83\uc774 \uc544\ub2c8\ub77c, `src/features/comments`\uc640 \uac19\uc774 \ud2b9\uc815 \uae30\ub2a5 \ub2e8\uc704\ub85c \ud3f4\ub354\ub97c \uad6c\uc131\ud55c\ub2e4. \ud574\ub2f9 \uae30\ub2a5\uc5d0\uc11c\ub9cc \uc0ac\uc6a9\ud558\ub294 \ub85c\uc9c1\uacfc \ucef4\ud3ec\ub10c\ud2b8\ub97c \ud55c \ud3f4\ub354\uc5d0\uc11c \uad00\ub9ac\ud558\ub294 \ubc29\uc2dd\uc774\ub2e4.\\r\\n![alt text](img/bulletproof.png)\\r\\n\\r\\n## FSD(Feature-Sliced Design)\\r\\n\\r\\nFSD\ub294 \uc5ec\uae30\uc11c \ub354 \ub098\uc544\uac00 **\uacc4\uce35\ud654**\ub97c \ud1b5\ud574 \uc5c4\uaca9\ud558\uac8c \uc758\uc874\uc131\uc744 \uad00\ub9ac\ud560 \uac83\uc744 \uc81c\uc548\ud55c\ub2e4. \uac00\uc7a5 \ud070 \ud2b9\uc9d5\uc740 **\ub2e8\ubc29\ud5a5 \uc758\uc874\uc131**\uc73c\ub85c, \ud558\uc704 \uacc4\uce35\uc774 \uc0c1\uc704 \uacc4\uce35\uc744 \uc808\ub300 \ucc38\uc870\ud560 \uc218 \uc5c6\uac8c \uc124\uacc4\ud558\uc5ec \ucf54\ub4dc \uac04 \uc21c\uc11c\ub97c \uba85\ud655\ud788 \uc815\uc758\ud55c\ub2e4.\\r\\n\\r\\n- **App**: \uc571\uc758 \uc9c4\uc785\uc810 (Provider, \uc804\uc5ed \uc2a4\ud0c0\uc77c)\\r\\n- **Processes**: \uc5ec\ub7ec \ub2e8\uacc4\uac00 \ud544\uc694\ud55c \ube44\uc988\ub2c8\uc2a4 \ub85c\uc9c1\\r\\n- **Pages**: \uc2e4\uc81c \ud654\uba74 \ub2e8\uc704\\r\\n- **Widgets**: \ub3c5\ub9bd\uc801\uc778 \ud070 \ub2e8\uc704 (Header, Sidebar)\\r\\n- **Features**: \uc0ac\uc6a9\uc790 \ud589\ub3d9 (\uc88b\uc544\uc694 \ubc84\ud2bc, \uac80\uc0c9 \ucc3d)\\r\\n- **Entities**: \ube44\uc988\ub2c8\uc2a4 (User, Product, Post)\\r\\n- **Shared**: \uacf5\ud1b5 UI \ucef4\ud3ec\ub10c\ud2b8, \uc720\ud2f8 \ud568\uc218\\r\\n\\r\\n\\r\\n## \uc801\uc6a9\ud574\ubcf4\uae30\\r\\n\\r\\n\ub9ac\ud329\ud1a0\ub9c1 \uacfc\uc815 \uc911 \uc774\ub7ec\ud55c \ud3f4\ub354 \uad6c\uc870\ub97c \ub530\ub77c\uac00\ubcf4\uace0 \uc788\ub2e4. \uae30\uc874\uc5d0\ub294  `component` \ud3f4\ub354\uc640 `features `\ud3f4\ub354\uc5d0 \ub85c\uc9c1\uc774 \ubab0\ub824\uc788\uc5c8\uace0, \uc774\ub97c \uac01\uac01 `features` \ud3f4\ub354 \ub0b4\ubd80\ub85c \ubd84\uc0b0\uc2dc\ucf30\ub2e4.\\r\\n\\r\\n![alt text](img/noiton-folder.png)\\r\\n\\r\\n- `src/features/template/hooks/useDownloadTemplate.ts`\\r\\n- `src/features/template/service/tempolateService.ts`\\r\\n\\r\\n\uae30\ub2a5\uc744 \uc0c8\ub85c \uac1c\ubc1c\ud560\ub54c `features` \ud3f4\ub354 \uc548\uc5d0 \uc0c8\ub85c\uc6b4 \ud3f4\ub354\ub97c \ub9cc\ub4e4\uae30\ub9cc \ud558\uba74 \ub41c\ub2e4\ub294 \ud3ec\uc778\ud2b8\uac00 \uc911\uc694\ud55c \uac83 \uac19\ub2e4. \uae30\ub2a5\uc744 \uc0ad\uc81c\ud558\uac70\ub098, \uad00\ub828 \ud568\uc218\ub97c \ud14c\uc2a4\ud2b8\ud560\ub54c \ud3f4\ub354 \ud558\ub098\ub9cc \ud655\uc778\ud558\uba74 \ub41c\ub2e4\ub294 \uac83\uc774 \uc791\uc5c5\uc5d0 \ub9e4\uc6b0 \ud6a8\uc728\uc801\uc774\uace0 \ud3b8\ub9ac\ud558\ub2e4.\\r\\n\\r\\n## Hook \uacfc API\ub97c \ubd84\ub9ac\ud558\uc790\\r\\n\\r\\n\uc791\uc740 \ud504\ub85c\uc81d\ud2b8\uc5d0 \uc774\ub7f0 \uc5c4\uaca9\ud55c \uad6c\uc870\ub97c \ub3c4\uc785\ud558\ub294 \uac83\uc774 \ubc88\uac70\ub86d\uac8c \ub290\uaef4\uc9c8 \uc218 \uc788\ub2e4. \ud558\uc9c0\ub9cc \uc9c1\uc811 \uc801\uc6a9\ud558\uba70 \ub290\ub080 \uc810\uc740 **\uaddc\ubaa8\uc640 \uc0c1\uad00\uc5c6\uc774 \uad00\uc2ec\uc0ac\ub97c \ubd84\ub9ac\ud558\ub294 \uc2b5\uad00\uc774 \ud544\uc218\uc801\uc774\ub2e4**\ub294 \uc810\uc774\ub2e4.\\r\\n\\r\\n\ucef4\ud3ec\ub10c\ud2b8\uc5d0\uc11c \uc9c1\uc811 `API`\ub97c \ud638\ucd9c\ud558\ub294 \ub300\uc2e0, `service`\ub85c \ud1b5\uc2e0\uc744 \ubd84\ub9ac\ud558\uace0 \uc774\ub97c \ucee4\uc2a4\ud140 `hook`\uc73c\ub85c \uac10\uc2f8\ub294 \uad6c\uc870\ub97c \ucd94\ucc9c\ud55c\ub2e4. \uc774\ub807\uac8c \ud558\uba74 \ub098\uc911\uc5d0 `TanStack Query`\ub97c \ub3c4\uc785\ud558\uac70\ub098 \ub099\uad00\uc801 \uc5c5\ub370\uc774\ud2b8 \ub85c\uc9c1\uc744 \ucd94\uac00\ud560 \ub54c, `UI` \ucf54\ub4dc\ub294 \ub2e8 \ud55c \uc904\ub3c4 \uac74\ub4dc\ub9ac\uc9c0 \uc54a\uace0 \ub85c\uc9c1\ub9cc \uae54\ub054\ud558\uac8c \uad50\uccb4\ud560 \uc218 \uc788\ub2e4.\\r\\n\\r\\n## \ub9c8\ubb34\ub9ac\\r\\n\\r\\n\uadf8\ub7fc\uc5d0\ub3c4 \uc644\ubcbd\ud55c \ud3f4\ub354 \uad6c\uc870\ub780 \uac74 \uc5c6\ub2e4.  \\r\\n\uae30\uc220\uc740 \ubcc0\ud654\ud558\uace0, \uadf8\ub7f0 \uae30\uc220\uc5d0 \ub9de\ub294 \uc0c8\ub85c\uc6b4 \uad6c\uc870\uac00 \ub4f1\uc7a5\ud560 \uc218 \uc788\ub2e4.  \\r\\n\uadf8\ub7fc\uc73c\ub85c \uc720\uc9c0\ubcf4\uc218\ud558\uae30 \uc88b\uc740 \uad6c\uc870\uc5d0 \ub300\ud55c \uace0\ubbfc\uc744 \uacc4\uc18d \ud574\uac00\uba70 \ud559\uc2b5\ud574\ub098\uac00\uc57c\uaca0\ub2e4."},{"id":"next-sidepj","metadata":{"permalink":"/blog/next-sidepj","editUrl":"https://github.com/eeheueklf/eeheueklf.github.io/tree/main/blog/2026-03-21.md","source":"@site/blog/2026-03-21.md","title":"Next.js\uac00 \ud568\uc815\uc774\uc5c8\ub358 \ud0c0\uc790 \uc5f0\uc2b5 \ud504\ub85c\uc81d\ud2b8 \ud68c\uace0","description":"\ucd5c\uc2e0 \ud2b8\ub80c\ub4dc\uc778 Next.js\ub97c \ud559\uc2b5\ud558\uace0 \uc801\uc6a9\ud588\ub358 \uc801\uc6a9\uae30\uc785\ub2c8\ub2e4.","date":"2026-04-05T00:00:00.000Z","formattedDate":"2026\ub144 4\uc6d4 5\uc77c","tags":[],"readingTime":3.795,"hasTruncateMarker":false,"authors":[],"frontMatter":{"slug":"next-sidepj","title":"Next.js\uac00 \ud568\uc815\uc774\uc5c8\ub358 \ud0c0\uc790 \uc5f0\uc2b5 \ud504\ub85c\uc81d\ud2b8 \ud68c\uace0","date":"2026-04-05T00:00:00.000Z"},"unlisted":false,"prevItem":{"title":"\ud83e\udd16Gemini\uc640 \uc54c\uc544\ubcf8 \ud604\uc5c5\uc5d0\uc11c \uc4f0\ub294 \ud3f4\ub354 \uad00\ub9ac","permalink":"/blog/feature-sliced-design"},"nextItem":{"title":"\ube14\ub85c\uadf8 \uc0c8 \ub2e8\uc7a5 with Docusaurus\ud83e\udd95","permalink":"/blog/blog-docusaurus"}},"content":"*\ucd5c\uc2e0 \ud2b8\ub80c\ub4dc\uc778 Next.js\ub97c \ud559\uc2b5\ud558\uace0 \uc801\uc6a9\ud588\ub358 \uc801\uc6a9\uae30\uc785\ub2c8\ub2e4.*\\n\\n\ube14\ub85c\uadf8\ub97c \ub9cc\ub4e4\uba70 `Next.js`\ub97c \ub9db\ubcf8 \ub4a4, **\uc774\uac70 \ubb3c\uac74\uc774\ub2e4**\ub77c\ub294 \uc0dd\uac01\uc774 \ub4e4\uc5c8\ub2e4.\\n\\n\ubc30\ud3ec\ub3c4 \ube60\ub974\uace0 \ub9ac\uc561\ud2b8\ub791\ub3c4 \ube44\uc2b7\ud574\uc11c, \ubc14\ub85c \ub2e4\uc74c \ud504\ub85c\uc81d\ud2b8 \ud504\ub808\uc784\uc6cc\ud06c\ub85c \uc120\ud0dd\ud588\ub2e4.\\n\\n\uadf8\ub807\uac8c 2\uba85\uc774\uc11c \uc57c\uc2ec\ucc28\uac8c \uc2dc\uc791\ud55c \ud0c0\uc790 \uc5f0\uc2b5 \uc0ac\uc774\ud2b8 \uc0ac\uc774\ub4dc \ud504\ub85c\uc81d\ud2b8 \\n[TYLE](https://tyletype.vercel.app)\\n\\n\\n![TYLE](./img/TYLE.png)\\n\\n\ucc98\uc74c\uc5d4 \ubaa8\ub4e0 \uac8c \uc21c\uc870\ub85c\uc6e0\ub2e4.\\n\\n`Vercel`\uc5d0\uc11c\uc758 \ubc30\ud3ec\ub294 \uc21c\uc2dd\uac04\uc774\uc5c8\uace0, \ub9ac\uc561\ud2b8 \ud588\ub358\ub300\ub85c \uad6c\ud604\ub3c4 \ube60\ub974\uac8c \ud588\ub2e4.\\n\\n\ud558\uc9c0\ub9cc \ud504\ub85c\uc81d\ud2b8\uac00 \uc9c4\ud589\ub420\uc218\ub85d \ubb54\uac00 \uc774\uc0c1\ud568\uc744 \ub290\uaf08\ub2e4.\\n\\n![\uc774\uc0c1\ud558\ub2e4](./img/\uc774\uc0c1\ud558\ub2e4.png)\\n\\n**1. \uc774\uac70 `use Client` \uc774\ub807\uac8c \ub9ce\uc774 \uc4f0\uba74 \uc548\ub420 \uac83 \uac19\uc740\ub370**\\n\\n`Next.js`\uac00 \uc11c\ubc84 \uc0ac\uc774\ub4dc \ub80c\ub354\ub9c1`SSR`\uc5d0 \uac15\uc810\uc774 \uc788\uc74c\uc5d0\ub3c4 \uc0ac\uc774\ud2b8 \ucd08\uae30 \uba54\uc778\ud654\uba74 \ub80c\ub354\ub9c1 \uc18d\ub3c4\uac00 \ub108\ubb34 \uae38\uc5c8\ub2e4. \\n\\n\ud0c0\uc790 \uc5f0\uc2b5 \ud2b9\uc131\uc0c1 \uc2e4\uc2dc\uac04 \ud0a4\ubcf4\ub4dc \uc774\ubca4\ud2b8\uc640 \uc0c1\ud0dc \uc5c5\ub370\uc774\ud2b8\uac00 70% \uc774\uc0c1\uc774\uc5c8\uae30 \ub54c\ubb38\uc5d0 \ud654\uba74\uc5d0 \uac70\uc758 \ubaa8\ub4e0 \uacf3\uc5d0 `use client`\uac00 \ud544\uc694\ud588\ub2e4!\\n\\n\\n**2. SEO \uc4f8\ub370\uac00 \uc5c6\ub124**\\n\\n\uac80\uc0c9 \uc5d4\uc9c4 \ucd5c\uc801\ud654\uac00 \uc7a5\uc810\uc774\ub77c\uc9c0\ub9cc, \ud0c0\uc790 \uc5f0\uc2b5 \uc0ac\uc774\ud2b8\uc5d4 \ud14d\uc2a4\ud2b8 \ucf58\ud150\uce20\uac00 \uc5c6\uae30 \ub54c\ubb38\uc5d0\\n\\n\ud0a4\ubcf4\ub4dc\uc640 \uae00\uadc0\ub9cc \uc788\ub294 \uc11c\ube44\uc2a4\uc5d0\uc11c \uc7a5\uc810\uc744 \ubc1c\ud718 \ud560 \uc218\uac00 \uc5c6\uc5c8\ub2e4.\\n\\n\\n**3. \ud55c\uae00 \uc785\ub825\uacfc \ub80c\ub354\ub9c1**\\n\\n\ud55c\uae00 \uc785\ub825\uc740 \uc790+\ubaa8\uc74c\uc774 \ud569\uccd0\uc9c0\ub294 \ud615\ud0dc\ub77c \ud2b9\uc218\ud55c \uacbd\uc6b0\uc600\ub294\ub370..  \\n \uc870\ud569 \uc911\uc778 \uae00\uc790\uac00 \uc0c1\ud0dc\uc640 \ub3d9\uae30\ud654\ub420 \ub54c\ub9c8\ub2e4 \ubd88\ud544\uc694\ud55c \ub9ac\ub80c\ub354\ub9c1\uc774 \ube48\ubc88\ud558\uac8c \ubc1c\uc0dd\ud588\ub2e4. \ub610\ud55c \uc5d4\ud130 \ud0a4 \uc785\ub825 \uc2dc \uc774\ubca4\ud2b8\uac00 \uc911\ubcf5\uc73c\ub85c \ubc1c\uc0dd\ud558\ub294 \ub4f1 \ud074\ub77c\uc774\uc5b8\ud2b8 \uce21\uc5d0\uc11c \ucc98\ub9ac\ud574\uc57c \ud560 \uc5e3\uc9c0 \ucf00\uc774\uc2a4\uac00 \ub9ce\uc558\ub2e4.\\n\\n\uacb0\uad6d \uc11c\ube44\uc2a4\uc758 \ud575\uc2ec\uc778 \ud0c0\uc774\ud551 \ub85c\uc9c1\uc740 \uc21c\uc218 \ud074\ub77c\uc774\uc5b8\ud2b8 \uc601\uc5ed\uc774\uc5c8\uace0 \uc131\ub2a5 \ucd5c\uc801\ud654\uc758 \ud575\uc2ec \ub610\ud55c \ud074\ub77c\uc774\uc5b8\ud2b8 \uce21\uc5d0 \uc788\uc5c8\ub2e4. `Next.js`\uc758 \uc7a5\uc810\uc744 \uc0b4\ub9ac\uc9c0 \ubabb\ud558\uace0 \uc624\ud788\ub824 \uc544\ud0a4\ud14d\ucc98\ub9cc \ubcf5\uc7a1\ud574\uc9c0\ub294 \uacb0\uacfc\uc600\ub2e4.\\n\\n## \uae30\uc220\uc740 \ub3c4\uad6c\uc77c \ubfd0\uc774\ub2e4!\\n\uace0\ubbfc \uc5c6\ub294 \uae30\uc220 \ub3c4\uc785\uc740 \uc624\ud788\ub824 \uc124\uacc4\uc758 \ubcf5\uc7a1\ub3c4\ub97c \ub192\uc774\uace0 \uac1c\ubc1c \uc0dd\uc0b0\uc131\uc744 \uc800\ud574\ud55c\ub2e4. \ud2b8\ub80c\ub4dc\uc5d0 \ub530\ub77c `Next.js`\ub97c \uc120\ud0dd\ud588\uc9c0\ub9cc, \ud0c0\uc790 \uc5f0\uc2b5\uacfc \uac19\uc774 \uc2e4\uc2dc\uac04 \uc778\ud130\ub799\uc158 \ube44\uc911\uc774 \ub192\uc740 \ud504\ub85c\uc81d\ud2b8\uc5d0\uc11c\ub294 \ub354 \uac00\ubcbc\uc6b4 \ud074\ub77c\uc774\uc5b8\ud2b8 \uc911\uc2ec\uc758 \ud658\uacbd\uc774 \uc801\ud569\ud588\ub2e4.\\n\\n\uacb0\uad6d \uac1c\ubc1c\uc790\uc758 \uc9c4\uc815\ud55c \uc2e4\ub825\uc740, \ud504\ub85c\uc81d\ud2b8\uc758 \uc131\uaca9\uc5d0 \ub9de\ub294 \uc801\uc808\ud55c \uae30\uc220\uc744 \uc120\ud0dd\ud558\ub294 \uc548\ubaa9\uc778 \uac83\uc774\ub2e4. \uc774\ub7ec\ud55c \uae68\ub2ec\uc74c\uc744 \uc0c8\uae30\uace0, \ub2e4\uc74c \ud504\ub85c\uc81d\ud2b8\uc5d0\uc11c\ub294 SEO\uc640 \ucd08\uae30 \ub85c\ub529 \uc18d\ub3c4\ub77c\ub294 \ubaa9\ud45c\ub97c \uc124\uc815\ud558\uace0, `Next.js`\uc758 \uae30\ub2a5\uc744 \uc81c\ub300\ub85c \ud65c\uc6a9\ud560 \uc218 \uc788\ub294 **\uc11c\ubc84 \ucef4\ud3ec\ub10c\ud2b8 \uc6b0\uc120 \uc124\uacc4**\ub97c \uc911\uc2ec\uc5d0 \ub450\uae30\ub85c \ud588\ub2e4.\\n\\n---\\n\\n> \ub2e4\uc74c \uae00 : [\ud55c\ubc88 \uae68\uc9c0\uace0 \ub2e4\uc2dc \ub2e4\uc9c4 Next.js](/docs/dev-log/noiton-render)"},{"id":"blog-docusaurus","metadata":{"permalink":"/blog/blog-docusaurus","editUrl":"https://github.com/eeheueklf/eeheueklf.github.io/tree/main/blog/2026-03-26.md","source":"@site/blog/2026-03-26.md","title":"\ube14\ub85c\uadf8 \uc0c8 \ub2e8\uc7a5 with Docusaurus\ud83e\udd95","description":"","date":"2026-03-26T00:00:00.000Z","formattedDate":"2026\ub144 3\uc6d4 26\uc77c","tags":[],"readingTime":0,"hasTruncateMarker":false,"authors":[],"frontMatter":{"slug":"blog-docusaurus","title":"\ube14\ub85c\uadf8 \uc0c8 \ub2e8\uc7a5 with Docusaurus\ud83e\udd95","date":"2026-03-26T00:00:00.000Z"},"unlisted":false,"prevItem":{"title":"Next.js\uac00 \ud568\uc815\uc774\uc5c8\ub358 \ud0c0\uc790 \uc5f0\uc2b5 \ud504\ub85c\uc81d\ud2b8 \ud68c\uace0","permalink":"/blog/next-sidepj"},"nextItem":{"title":"[\ud68c\uace0] \ud504\ub85c\uadf8\ub798\uba38\uc2a4 \uae30\ucd08 \uc785\ubb38 \ub2ec\uc131 \ud6c4\uae30 \ud83e\udd73\ud83c\udf89","permalink":"/blog/programmers"}},"content":""},{"id":"programmers","metadata":{"permalink":"/blog/programmers","editUrl":"https://github.com/eeheueklf/eeheueklf.github.io/tree/main/blog/2025-09-26.md","source":"@site/blog/2025-09-26.md","title":"[\ud68c\uace0] \ud504\ub85c\uadf8\ub798\uba38\uc2a4 \uae30\ucd08 \uc785\ubb38 \ub2ec\uc131 \ud6c4\uae30 \ud83e\udd73\ud83c\udf89","description":"\ud504\ub860\ud2b8\uc5d4\ub4dc \ucf54\ub529\ud14c\uc2a4\ud2b8 \uc900\ube44 \uacb8 JS \uae30\ubcf8\uae30 \uc775\ud788\uae30\ub97c \ubaa9\ud45c\ub85c \ud504\ub85c\uadf8\ub798\uba38\uc2a4 \uae30\ucd08 \ubc0f \uc785\ubb38 \ud2b8\ub808\uc774\ub2dd\uc744 3\uc8fc \ub3d9\uc548 \ud480\uc5c8\ub2e4.","date":"2025-09-25T00:00:00.000Z","formattedDate":"2025\ub144 9\uc6d4 25\uc77c","tags":[],"readingTime":2.29,"hasTruncateMarker":false,"authors":[],"frontMatter":{"slug":"programmers","title":"[\ud68c\uace0] \ud504\ub85c\uadf8\ub798\uba38\uc2a4 \uae30\ucd08 \uc785\ubb38 \ub2ec\uc131 \ud6c4\uae30 \ud83e\udd73\ud83c\udf89","sidebar_position":0,"date":"2025-09-25T00:00:00.000Z"},"unlisted":false,"prevItem":{"title":"\ube14\ub85c\uadf8 \uc0c8 \ub2e8\uc7a5 with Docusaurus\ud83e\udd95","permalink":"/blog/blog-docusaurus"},"nextItem":{"title":"\uc778\ud2b8\ub85c","permalink":"/blog/intro"}},"content":"\ud504\ub860\ud2b8\uc5d4\ub4dc \ucf54\ub529\ud14c\uc2a4\ud2b8 \uc900\ube44 \uacb8 JS \uae30\ubcf8\uae30 \uc775\ud788\uae30\ub97c \ubaa9\ud45c\ub85c \ud504\ub85c\uadf8\ub798\uba38\uc2a4 \uae30\ucd08 \ubc0f \uc785\ubb38 \ud2b8\ub808\uc774\ub2dd\uc744 3\uc8fc \ub3d9\uc548 \ud480\uc5c8\ub2e4.  \\n\uae30\ucd08\uc640 \uc785\ubb38 \uac01 25\uc77c\uc529 `Lv.0` \ubb38\uc81c\ub97c \ud480\uc5b4\ubcf4\ub294 \uacfc\uc815\uc774\uc5c8\ub294\ub370, \uc804\uacf5\uc790\ub77c \ud558\ub8e8\uc5d0 \uae30\ucd08+\uc785\ubb38 `2 Day`\uc529 \ub2ec\ub838\ub2e4.\\n\\n\ucd08\ubc18\uc5d0\ub294 1\uc2dc\uac04 \uc815\ub3c4 \uac78\ub838\uace0, \ud6c4\ubc18\uc5d0\ub294 2\uc2dc\uac04, \uc5b4\ub824\uc6b8 \ub54c\ub294 3\uc2dc\uac04\uae4c\uc9c0 \ubb38\uc81c \ud480\uc774\uc5d0 \uc2dc\uac04\uc744 \ub4e4\uc600\ub2e4.\\n\\n\uadf8\ub3d9\uc548 \ud504\ub860\ud2b8\uc5d4\ub4dc \uad6c\ud604\uc5d0 `JavaScript`\ub97c \uc4f0\uae34 \ud588\uc9c0\ub9cc \uae30\ucd08\ubd80\ud130 \uccb4\uacc4\uc801\uc73c\ub85c \ubc30\uc6b4 \uac74 \uc544\ub2c8\uc5c8\ub2e4. \uadf8\ub798\uc11c \uba54\uc11c\ub4dc \ud558\ub098\ud558\ub098 \uc54c\uc544\uac00\uba74\uc11c \ud480\uc5c8\ub294\ub370, \uacfc\uc815\uc744 \uc644\ub8cc\ud558\ub294 \uc2dc\uc810\uc5d0\uc11c \ubcf4\ub2c8 \uac01 \uba54\uc11c\ub4dc\uc758 \uc4f0\uc784\uc0c8\ub97c \uc775\ud788\uace0 \ubb38\uc790\uc5f4\uacfc \ubc30\uc5f4\uc744 \uc9d1\uc911\uc801\uc73c\ub85c \uacf5\ub7b5\ud560 \uc218 \uc788\uc5b4\uc11c \uc88b\uc558\ub2e4.\\n\\n\ub4dc\ub514\uc5b4 JS\uc758 \uae30\ucd08\ub97c \uc81c\ub300\ub85c \ub5c0 \ub290\ub08c \ud83d\ude0a\ud83d\ude05\\n\\n\\n![alt text](./img/emoji1.png)\\n\\n\\n`Lv.0`\uc778\ub370\ub3c4 \uc27d\uc9c0 \uc54a\uc740 \ubb38\uc81c\ub4e4\uc774 \uc11e\uc5ec \uc788\uc5c8\uc9c0\ub9cc, `JavaScript`\uc5d0\ub294 \ub2e4\ub978 \uc5b8\uc5b4\uc5d0\uc11c \ubcfc \uc218 \uc5c6\ub294 \uae30\ud2b9\ud55c \uba54\uc11c\ub4dc\uac00 \ucc38 \ub9ce\uc558\ub2e4. \uae38\uac8c \ud480\uc5b4\uc57c \ud560 \ub85c\uc9c1\uc744 \ud55c \uc904\ub85c \uc904\uc5ec\uc8fc\ub294 \uba54\uc11c\ub4dc\ub4e4\uc744 \ubcf4\uba70 \ud655\uc2e4\ud788 `\uc544\ub294\uac8c \ud798\uc774\ub2e4` \ub77c\ub294\uac78 \ub290\uaf08\ub2e4\\n\\n\\n\\n`Lv.0`\uc744 \ub05d\ub0c8\uc73c\ub2c8 \uc774\uc81c `Lv.1`\uc744 \ucc28\uadfc\ucc28\uadfc \ud480\uc5b4\ubcfc \uc608\uc815\uc774\ub2e4. \uc870\uae08 \ud480\uc5b4 \ubcf4\ub2c8\uae4c `Lv.0`\uc5d0\uc11c \uae30\ucd08\ub97c \ud0c4\ud0c4\ud788 \ub2e4\uc84c\ub2e4\uba74 `Lv.1`\ub3c4 \ud070 \uc5b4\ub824\uc6c0\uc740 \uc5c6\uc744 \uac83 \uac19\ub2e4! \\n\\n\ucc38\uace0\ub85c \ucd08\ubc18\uc5d0\ub294 \uae30\ucd08\uc640 \uc785\ubb38 \ub09c\uc774\ub3c4\uac00 \ube44\uc2b7\ud558\uc9c0\ub9cc, \uc785\ubb38 \ud6c4\ubc18\uc73c\ub85c \uac08\uc218\ub85d \uc5b4\ub824\uc6cc\uc9c4\ub2e4. \uae30\ucd08\uc640 \uc785\ubb38\uc744 \ub530\ub85c \uc9c4\ud589\ud560 \uc0dd\uac01\uc774\ub77c\uba74 \uae30\ucd08 \u2192 \uc785\ubb38 \uc21c\uc11c\ub85c \uacf5\ubd80\ud558\ub294 \uac83\uc744 \ucd94\ucc9c\ud55c\ub2e4.\\n\\n![\ud504\ub85c\uadf8\ub798\uba38\uc2a4 \uc644\ub8cc \uce98\ub9b0\ub354](./img/programmers-cal.png)"},{"id":"intro","metadata":{"permalink":"/blog/intro","editUrl":"https://github.com/eeheueklf/eeheueklf.github.io/tree/main/blog/2025-08-27.md","source":"@site/blog/2025-08-27.md","title":"\uc778\ud2b8\ub85c","description":"\ud83e\uddf1\ud83e\uddf1\ud83e\uddf1\ud83e\uddf1\ud83e\uddf1\ud83e\uddf1\ud83e\uddf1\ud83e\uddf1\ud83e\uddf1\ud83e\uddf1","date":"2025-08-27T00:00:00.000Z","formattedDate":"2025\ub144 8\uc6d4 27\uc77c","tags":[],"readingTime":1.4,"hasTruncateMarker":false,"authors":[],"frontMatter":{"slug":"intro","title":"\uc778\ud2b8\ub85c","date":"2025-08-27T00:00:00.000Z"},"unlisted":false,"prevItem":{"title":"[\ud68c\uace0] \ud504\ub85c\uadf8\ub798\uba38\uc2a4 \uae30\ucd08 \uc785\ubb38 \ub2ec\uc131 \ud6c4\uae30 \ud83e\udd73\ud83c\udf89","permalink":"/blog/programmers"}},"content":"\ud83e\uddf1\ud83e\uddf1\ud83e\uddf1\ud83e\uddf1\ud83e\uddf1\ud83e\uddf1\ud83e\uddf1\ud83e\uddf1\ud83e\uddf1\ud83e\uddf1\\n\\n## \ub9c8\ud06c\ub2e4\uc6b4 \ucc38\uace0\ud558\uae30 \ud83c\udf6a\ud83c\udf44\u200d\ud83d\udfeb\u2615\\n### \ud83d\udc4b \uc548\ub155\ud558\uc138\uc694 \ud83e\udd0e\ud83e\uddf8\ud83d\udcdc\\n#### \uc81c\ubaa9 4 \ud83c\udf15\ud83c\udf5e\ud83c\udf42\\n \ud83c\udf69\ud83d\udc3f\ufe0f\ud83c\udf66\\n\\n## 1. alert\\n\\n:::note\\n\uc815\ubcf4\\n:::\\n\\n:::tip\\n\ud301\\n:::\\n\\n:::warning\\n\uba54\ubaa8\\n:::\\n\\n:::danger\\n\uacbd\uace0\\n:::\\n:::danger Take care\\n\\n\uacbd\uace0\uc785\ub2c8\ub2e4~\\n\\n:::\\n---\\n\\n\\n## 2. \ud14d\uc2a4\ud2b8 \uc2a4\ud0c0\uc77c\\n**\uad75\uac8c**  \\n*\uae30\uc6b8\uc784*  \\n~~\ucde8\uc18c\uc120~~  \\n**\uad75\uace0 _\uae30\uc6b8\uc784_**\\n\\n---\\n\\n## 3. \ubaa9\ub85d\\n### \uc21c\uc11c \uc5c6\ub294 \ubaa9\ub85d\\n- \uc544\uc774\ud15c 1\\n- \uc544\uc774\ud15c 2\\n  - \ud558\uc704 \uc544\uc774\ud15c\\n\\n### \uc21c\uc11c \uc788\ub294 \ubaa9\ub85d\\n1. \uccab \ubc88\uc9f8\\n2. \ub450 \ubc88\uc9f8\\n   1. \ud558\uc704 \uccab \ubc88\uc9f8\\n\\n---\\n\\n## 5. \ucf54\ub4dc\\n```js\\nconsole.log(\\"JavaScript \ucf54\ub4dc \ube14\ub85d\\");\\n```\\n\\n---\\n\\n## 6. \uc778\uc6a9\ubb38\\n> \uc778\uc6a9\ubb38\uc785\ub2c8\ub2e4.\\n>> \uc911\ucca9 \uc778\uc6a9\ubb38\uc785\ub2c8\ub2e4.\\n\\n\\n---\\n\\n## 8. \uccb4\ud06c\ubc15\uc2a4 (GFM)\\n- [x] \uc644\ub8cc\\n- [ ] \ubbf8\uc644\ub8cc\\n\\n---\\n\\n\\n## 10. \uac01\uc8fc\\n\ubb38\uc7a5 \uc548\uc5d0\uc11c \uac01\uc8fc\ub97c \ub2ec \uc218 \uc788\uc2b5\ub2c8\ub2e4[^1].\\n\\n[^1]: \uac01\uc8fc \ub0b4\uc6a9\\n\\n---\\n\\n## 12. \ud615\uad11\ud39c\\n<mark>\uae30\ubcf8 \ud615\uad11\ud39c</mark>\uc774\uc796\uc544~\\n\\n\\n\\n\\n\\n\\n---\\n\\n## 14. \ucf54\ub4dc \ube14\ub85d\\n```js {1,4}\\nfunction hello() {\\n  console.log(\\"2\ubc88 \uc904 \ud558\uc774\ub77c\uc774\ud2b8\\");\\n}\\nconsole.log(\\"4\ubc88 \uc904 \ud558\uc774\ub77c\uc774\ud2b8\\");\\nconsole.log(\\"4\ubc88 \uc904 \ud558\uc774\ub77c\uc774\ud2b8\\");\\nconsole.log(\\"4\ubc88 \uc904 \ud558\uc774\ub77c\uc774\ud2b8\\");\\n```\\n```jsx title=\\"src/pages/my-react-page.js\\"\\nimport React from \'react\';\\nimport Layout from \'@theme/Layout\';\\n\\nexport default function MyReactPage() {\\n  return (\\n    <Layout>\\n      <h1>My React page</h1>\\n      <p>This is a React page</p>\\n    </Layout>\\n  );\\n}\\n```\\n\\n\\n---\\n\\n\\n<details>\\n  <summary>Toggle me!</summary>\\n\\n  This is the detailed content\\n\\n  ```js\\n  console.log(\\"Markdown features including the code block are available\\");\\n  ```\\n</details>"}]}')}}]);